// A three.js module of a given size: the scene rule with its own length limit, and the instruction to start writing.
const SETTLED = 'The interface and the method are settled: do not deliberate at length before writing — start writing, and finish first.';
const sizedScene = (task: string, limit: number) => code(`${task} ${SETTLED} ${SCENE.replace('at most 10,000 characters', `at most ${limit.toLocaleString('en-US')} characters`)}`);
const sizedCode = (task: string, limit: number) => code(`${task} ${SETTLED} Write compactly with no comments. Output only the code, at most ${limit.toLocaleString('en-US')} characters.`);
// For a build that pastes four or more upstream modules (a simulation, a layout and several scene and interface
// modules): the page holds every one of them as delivered, so it gets the room they take. The car plant's page ran at
// this size on 2026-10-12 and 10-13 (its modules came to about 30,000 characters) and finished well inside one call.
const MODULE_ASSEMBLY = ASSEMBLY_RULES.replace('at most 24,000 characters', 'at most 36,000 characters');
const assembleModules = (task: string) => task + MODULE_ASSEMBLY;
const swap = (text: string, from: string, to: string) => {
  if (!text.includes(from)) throw new Error(`rule text changed: ${from.slice(0, 60)}`);
  return text.replace(from, to);
};
// Two steps for the larger games and apps, after a tower defense whose one-step build ran out of its call on 2026-10-13
// (19:09Z, output_limit at 32,000 tokens, its modules about 46,000 characters): a wiring node reads every module and
// writes only the code that connects them — it may think as long as it needs, since what it writes is short — and the
// page node then only pastes the modules and the wiring into one HTML frame, which leaves its call to the writing.
const WIRING_RULES = 'This code runs last, after every upstream module in the same script, and it is the program’s entry point: use the modules’ functions and objects by the names they delivered (read them in your inputs) and never redefine or rewrite any of them. The code must run as pasted: every bracket closed and no ellipses; it starts the program itself, and it never reads an object before it is created. Write compactly with no comments. Output only the code, at most';
const wiring = (task: string, limit: number) => `${task} ${WIRING_RULES} ${limit.toLocaleString('en-US')} characters.`;
const PASTE_RULES = swap(swap(swap(ASSEMBLY_RULES, 'at most 24,000 characters', 'at most 56,000 characters'),
  'This step only assembles: paste the 3D code delivered upstream exactly as delivered — never rewritten, trimmed or wrapped again — and write only the page structure, the interface, the interaction and the code that connects the modules. Do not redesign the look or deliberate at length before writing — start writing.',
  'This step only pastes: put every upstream module and then the wiring code into the page’s one script, in the order given, exactly as delivered — never rewritten, trimmed or wrapped again — and write only the HTML frame around them (the doctype, the head with the title and a minimal body style, the script tags). Do not redesign anything or deliberate before writing — start writing at once.'),
  'The look must reach the commercial key-art standard of this case’s cover: complete lighting and depth (ambient and key light, soft shadows, fog or depth of field), detail and material quality, fluid motion and particles — never wireframes, grey models or diagrams.',
  'The look and the behaviour are the modules’ own: add nothing to them.');
const paste = (task: string) => task + PASTE_RULES;

// three.js r186 (`stack: 'r186'`, 2026-10-15): the release AwwO's previews supply as ES modules (previewModules.ts),
// with physically based materials lit by an environment map and a bloom pass — what the r128 rules above could not
