// these imports, so every module and the wiring use THREE and these names and import nothing themselves.
const R186_IMPORTS = "import * as THREE from 'three'; import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js'; "
  + "import { RenderPass } from 'three/addons/postprocessing/RenderPass.js'; import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js'; "
  + "import { OutputPass } from 'three/addons/postprocessing/OutputPass.js'; import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js'; "
  + "import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js'; import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';";
const R186_NAMES = 'THREE, EffectComposer, RenderPass, UnrealBloomPass, OutputPass, RoomEnvironment, RoundedBoxGeometry and mergeGeometries';
const R128_LINE = 'Use three.js r128 for 3D, referenced only by this one line: ' + THREE_R128 + ' (AwwO replaces it with its own built-in copy of that release, so the page stays self-contained and needs no network — the platform’s delivery rule against external libraries or scripts does not apply to this one line; THREE.CapsuleGeometry is available when a capsule is needed).';
const R186_LINE = 'Use three.js r186 for 3D, loaded only through this import map in the head: ' + THREE_MODULES_IMPORT_MAP + ' (AwwO supplies that release’s files with its own built-in copies, so the page needs no network — the platform’s rule against external libraries does not apply to this import map). Its one <script type="module"> begins with exactly these lines: ' + R186_IMPORTS;
const R128_ONLY = 'Apart from that, no external scripts, module imports, fonts, images or audio files';
const R186_ONLY = 'Apart from that, no external scripts, other imports, fonts, images or audio files';
/** How a renderer is set up on r186, for the node that creates it. */
const R186_RENDERING = 'On r186 light is physical: scene.environment is a PMREM environment (PMREMGenerator.fromScene) so metal, paint and glass reflect; hemisphere and directional lights 1–3, point and spot lights in candela (tens to hundreds); ACESFilmic tone mapping; one DirectionalLight casts PCF soft shadows (2048). Every frame renders through an EffectComposer: RenderPass, UnrealBloomPass (strength 0.6–1.1, radius 0.5, threshold 0.75: only emissive and very bright parts glow), OutputPass; the renderer, the composer and the bloom follow the window size.';
/** For an upstream module on r186: what it may use, and how its materials are made. */
const R186_SCENE = `The code uses ${R186_NAMES} (three.js r186), which the page's module script imports at its top, and never imports anything itself; it references no external resource and generates textures on a canvas (colorSpace = THREE.SRGBColorSpace for colour); its materials are MeshStandardMaterial or MeshPhysicalMaterial, which the scene's environment map lights and reflects, so metal and glass may use full metalness, and glowing parts are emissive with emissiveIntensity 2–5 for the bloom; keep it compact, with no comments. Output only the code, at most 10,000 characters.`;
const r186Scene = (task: string, limit: number) => code(`${task} ${SETTLED} ${R186_SCENE.replace('at most 10,000 characters', `at most ${limit.toLocaleString('en-US')} characters`)}`);
const R186_WIRING = swap(WIRING_RULES, 'and never redefine or rewrite any of them.',
  `and never redefine or rewrite any of them; it also uses ${R186_NAMES}, which the page's module script imports at its top, and imports nothing itself.`);
const r186Wiring = (task: string, limit: number) => `${task} ${R186_RENDERING} ${R186_WIRING} ${limit.toLocaleString('en-US')} characters.`;
const R186_PASTE = swap(swap(swap(PASTE_RULES, R128_LINE, R186_LINE), R128_ONLY, R186_ONLY),
  'and write only the HTML frame around them (the doctype, the head with the title and a minimal body style, the script tags).',
  'and write only the HTML frame around them (the doctype, the head with the title, the import map and a minimal body style, and the one module script, which begins with the import lines above).');
const r186Paste = (task: string) => task + R186_PASTE;

