const r186bScene = (task: string, limit: number) => code(`${task} ${SETTLED} ${R186B_SCENE.replace('at most 10,000 characters', `at most ${limit.toLocaleString('en-US')} characters`)}`);
const R186B_WIRING = swap(WIRING_RULES, 'and never redefine or rewrite any of them.',
  `and never redefine or rewrite any of them; it also uses ${R186B_NAMES}, which the page's module script imports at its top, and imports nothing itself.`);
const r186bWiring = (task: string, limit: number) => `${task} ${R186_RENDERING} ${R186B_WIRING} ${limit.toLocaleString('en-US')} characters.`;
const R186B_PASTE = swap(swap(R186_PASTE, R186_LINE, R186B_LINE), R186_ONLY, R186B_ONLY);
const r186bPaste = (task: string) => task + R186B_PASTE;
