// The team knowledge-base SaaS: a working product on simulated data rather than a picture of one. Its team is the
// one its first run used (scope and architecture; access, documents and copy in parallel; the business layer; the
// web workspace; review), and every rule a role is held to lives in the business layer the page calls, not in the page.
const APP_RULES = swap(swap(ASSEMBLY_RULES,
  'paste the 3D code delivered upstream exactly as delivered', 'paste the code and data delivered upstream exactly as delivered'),
  'The look must reach the commercial key-art standard of this case’s cover: complete lighting and depth (ambient and key light, soft shadows, fog or depth of field), detail and material quality, fluid motion and particles — never wireframes, grey models or diagrams.',
  'The look must reach the standard of a leading SaaS product, as on this case’s cover: a clean, light interface with a clear hierarchy, consistent 8 px spacing, refined type, soft shadows and quiet transitions — never a bare wireframe or an unstyled form.');
const assembleApp = (task: string) => task + APP_RULES;

